import{_ as t,a,o as r,a4 as s}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Customers","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/customers/index.md","filePath":"api/rest-api/admin/customers/index.md","lastUpdated":1783079210000}'),o={name:"api/rest-api/admin/customers/index.md"};function n(i,e,d,c,l,h){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="customers" tabindex="-1">Customers <a class="header-anchor" href="#customers" aria-label="Permalink to &quot;Customers&quot;">​</a></h1><p>The Customers section is where you manage everyone who shops on the storefront and the records attached to them — their accounts, address books, internal notes, the groups they belong to, the product reviews they leave, and the privacy (GDPR) requests they raise. It also exposes the read-only panels an admin uses when <strong>building an order on a customer&#39;s behalf</strong>. It mirrors the admin <strong>Customers</strong> menu.</p><h2 id="menus" tabindex="-1">Menus <a class="header-anchor" href="#menus" aria-label="Permalink to &quot;Menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/customers/main/">Customers</a></td><td>The shopper accounts — create, view, edit, delete, suspend, and bulk-manage them. Each customer belongs to a Customer Group and carries order/spend totals.</td></tr><tr><td><a href="/api/rest-api/admin/customers/addresses/">Addresses</a></td><td>A customer&#39;s address book — billing/shipping addresses, with one marked default. Used at checkout and when an admin places an order for the customer.</td></tr><tr><td><a href="/api/rest-api/admin/customers/notes/">Notes</a></td><td>Append-only internal notes attached to a customer, optionally emailing the customer when added.</td></tr><tr><td><a href="/api/rest-api/admin/customers/impersonate/">Impersonate</a></td><td>&quot;Login as Customer&quot; — issues a short-lived customer token so an admin can act as that customer against the storefront API.</td></tr><tr><td><a href="/api/rest-api/admin/customers/groups/">Customer Groups</a></td><td>The named groups customers are sorted into (e.g. <em>general</em>, <em>wholesale</em>, <em>guest</em>). Groups drive group-specific pricing and promotions.</td></tr><tr><td><a href="/api/rest-api/admin/customers/reviews/">Reviews</a></td><td>Moderation queue for the product reviews customers submit on the storefront — approve, disapprove, delete.</td></tr><tr><td><a href="/api/rest-api/admin/customers/gdpr/">GDPR Requests</a></td><td>The privacy requests customers raise (data export or account deletion) and the workflow to action them.</td></tr><tr><td><a href="/api/rest-api/admin/customers/create-order-helpers/">Create-Order Helpers</a></td><td>Read-only panels — a customer&#39;s active cart, wishlist, and recent purchases — that feed the admin Create-Order flow.</td></tr></tbody></table><h2 id="how-these-records-relate" tabindex="-1">How these records relate <a class="header-anchor" href="#how-these-records-relate" aria-label="Permalink to &quot;How these records relate&quot;">​</a></h2><ul><li>A <strong>Customer</strong> always belongs to a <strong>Customer Group</strong>; the group decides which group-specific prices and promotions apply to them. Deleting a group is blocked while any customer still belongs to it.</li><li>A customer&#39;s <strong>Addresses</strong> are reused at checkout and when an admin builds an order for them through the <a href="/api/rest-api/admin/sales/orders/">Create Order</a> flow under Sales.</li><li><strong>Reviews</strong> originate on the storefront against catalog products; this menu is moderation only — admins change a review&#39;s status, they don&#39;t author reviews.</li><li><strong>GDPR Requests</strong> tie back to a customer: approving a <em>delete</em> request cascades into removing that customer&#39;s account and related data.</li><li><strong>Create-Order Helpers</strong> surface a customer&#39;s cart, wishlist, and recent items so an admin can quickly seed a draft cart when placing an order on their behalf.</li></ul><h2 id="rest-vs-graphql" tabindex="-1">REST vs. GraphQL <a class="header-anchor" href="#rest-vs-graphql" aria-label="Permalink to &quot;REST vs. GraphQL&quot;">​</a></h2><p>Over REST, each capability is its own endpoint — a separate request for the listing, the single record, and each write — and they are split by HTTP method (<code>GET</code> to read, <code>POST</code> to create, <code>PUT</code> to update, <code>DELETE</code> to remove). GraphQL combines a filtered listing with relation-loading and a single-record fetch in one query; the REST docs reflect the per-endpoint separation instead.</p><h2 id="conventions-across-the-customers-api" tabindex="-1">Conventions across the Customers API <a class="header-anchor" href="#conventions-across-the-customers-api" aria-label="Permalink to &quot;Conventions across the Customers API&quot;">​</a></h2><p>A few behaviours are common to every Customers menu over REST:</p><ul><li><strong>Listings are paginated.</strong> Every <code>GET</code> collection returns a <code>{ data, meta }</code> envelope; page with <code>?page=</code> and <code>?per_page=</code> (default 10, cap 50). Supplying multiple filter params narrows the result (logical AND).</li><li><strong>Nested objects, not flat ids.</strong> A customer&#39;s detail/list rows return the group as a nested <code>group</code> object; a review&#39;s detail returns nested <code>product</code> and <code>customer</code> objects plus an <code>images</code> array — no flat id/name columns to cross-reference.</li><li><strong>Detail-only fields.</strong> Aggregates and nested data (a customer&#39;s <code>totalOrders</code> / <code>totalAddresses</code> / <code>totalAmountSpent</code>, a review&#39;s images) are populated only on the single-record <code>GET</code>, not on the listing rows.</li><li><strong>Permission gates.</strong> Write operations are gated by the matching <code>customers.*</code> permission; an admin whose role lacks it gets a <code>403</code>.</li></ul><p>All Customers endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',12)]))}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
